const crypto = require('node:crypto');
const http = require('node:http');
const https = require('node:https');
const fetch = globalThis.fetch || ((urlString, options = {}) => new Promise((resolve, reject) => {
  const transport = String(urlString).startsWith('https://') ? https : http;
  const req = transport.request(urlString, {
    method: options.method || 'GET',
    headers: options.headers || {},
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk.toString();
    });
    res.on('end', () => {
      resolve({
        ok: (res.statusCode || 0) >= 200 && (res.statusCode || 0) < 300,
        status: res.statusCode || 0,
        text: async () => body,
        json: async () => body ? JSON.parse(body) : {},
      });
    });
  });
  req.on('error', reject);
  if (options.body) {
    req.write(options.body);
  }
  req.end();
}));

const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
if (!runnerBase) {
  throw new Error('AUTOMATION_RUNNER_BASE_URL env var is required');
}
const joinUrl = (base, pathname) => {
  if (!/^https?:\/\//.test(base)) {
    throw new Error(`Invalid AUTOMATION_RUNNER_BASE_URL: ${base}`);
  }
  return `${String(base).replace(/\/+$/, '')}${pathname}`;
};
const reportsWriteUrl = joinUrl(runnerBase, '/reports/write');
const contextUrl = joinUrl(runnerBase, '/context/last-github-event');
const jobsUrl = joinUrl(runnerBase, '/jobs');
const githubWebhookSecret = $env.GITHUB_WEBHOOK_SECRET;
if (!githubWebhookSecret) {
  throw new Error('GITHUB_WEBHOOK_SECRET env var is required');
}
const signatureHeader = String($json.headers?.['x-hub-signature-256'] ?? $json.headers?.['X-Hub-Signature-256'] ?? '').trim();
if (!signatureHeader) {
  throw new Error('Missing X-Hub-Signature-256 header');
}
const rawBodyValue = $json.rawBody;
if (typeof rawBodyValue !== 'string') {
  throw new Error('Missing rawBody for GitHub webhook signature verification');
}
const expectedSignature = `sha256=${crypto.createHmac('sha256', githubWebhookSecret).update(rawBodyValue).digest('hex')}`;
const providedSignature = Buffer.from(signatureHeader);
const expectedSignatureBuffer = Buffer.from(expectedSignature);
if (providedSignature.length !== expectedSignatureBuffer.length || !crypto.timingSafeEqual(providedSignature, expectedSignatureBuffer)) {
  return [{ json: { ok: false, statusCode: 401, error: 'Invalid GitHub webhook signature' } }];
}
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};
const payload = $json.body ?? $json;
const githubEvent = $json.headers?.['x-github-event'] ?? $json.headers?.['X-GitHub-Event'] ?? payload.event ?? 'unknown';
const isPrIssueComment = githubEvent === 'issue_comment' && payload.issue?.pull_request;
const reviewEvents = new Set(['pull_request_review', 'pull_request_review_comment']);
const prNumber = payload.pull_request?.number ?? payload.issue?.number ?? null;
const route = githubEvent === 'push'
  ? 'commit-summarizer'
  : githubEvent === 'pull_request'
    ? 'pr-review-first-pass'
    : githubEvent === 'issues'
      ? 'bug-triage'
      : (reviewEvents.has(githubEvent) || isPrIssueComment)
        ? 'pr-autofinish'
        : 'ignore';
const reportRelativePath = `github-events/${new Date().toISOString().replace(/[:]/g, '-')}-${githubEvent}.json`;
const writeResponse = await fetch(reportsWriteUrl, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: JSON.stringify({ githubEvent, route, payload }, null, 2) }),
});
if (!writeResponse.ok) throw new Error(`reports/write failed: ${writeResponse.status}`);
const putResponse = await fetch(contextUrl, {
  method: 'PUT',
  headers,
  body: JSON.stringify({ value: { githubEvent, route, reportRelativePath, receivedAt: new Date().toISOString(), prNumber } }),
});
if (!putResponse.ok) {
  const body = await putResponse.text();
  throw new Error(`context update failed: ${putResponse.status} ${body}`);
}
let jobResult = null;
if (route === 'pr-autofinish' && prNumber) {
  const jobResponse = await fetch(jobsUrl, {
    method: 'POST',
    headers,
    body: JSON.stringify({ action: 'pr_autofinish', mode: 'async', args: [String(prNumber)], dedupeKey: `pr-autofinish-${prNumber}` }),
  });
  const raw = await jobResponse.text();
  if (!jobResponse.ok && jobResponse.status !== 202) {
    throw new Error(`runner pr_autofinish failed: ${jobResponse.status} ${raw}`);
  }
  jobResult = raw ? JSON.parse(raw) : null;
}
return [{ json: { ok: true, githubEvent, route, prNumber, reportRelativePath, jobResult } }];
